CREATE TABLE catalog_categories (id TEXT PRIMARY KEY, label TEXT NOT NULL, sort_order INTEGER NOT NULL UNIQUE, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE catalog_offerings (id TEXT PRIMARY KEY, category_id TEXT NOT NULL REFERENCES catalog_categories(id), label TEXT NOT NULL, unit TEXT NOT NULL CHECK(unit IN('M2','ML','UN')), unit_price INTEGER NOT NULL CHECK(unit_price >= 0), sort_order INTEGER NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)), UNIQUE(category_id, sort_order));
